class AttachedWorkerRuntime:
    """Route and supervise normalized lifecycle events from an attached worker."""

    def __init__(
        self,
        *,
        model: ForemanModel,
        router: ResponsibilityRouter,
        responsibilities: ResponsibilityRegistry,
        config: FactoryConfig,
        store: AttachedSessionStore | None = None,
        routing_groups: tuple[RouteGroup, ...] = (),
        active_extension_ids: tuple[str, ...] = (),
        extension_snapshot_revisions: dict[str, str] | None = None,
    ) -> None:
        self.model = model
        self.router = router
        self.candidates = responsibilities
        self.config = config
        self.store = store or AttachedSessionStore(ttl_seconds=config.hook_session_ttl_seconds)
        self.routing_groups = routing_groups
        self.active_extension_ids = active_extension_ids
        self.extension_snapshot_revisions = dict(extension_snapshot_revisions or {})

    async def handle(self, event: HookEvent) -> HookOutcome:
        repository = _repository_root(event.cwd)
        self.store.purge_expired()
        with self.store.locked(event.session_id, event.client):
            if event.kind is HookEventKind.SESSION_ENDED:
                self.store.delete(event.session_id, event.client)
                return HookOutcome()

            session = self.store.load(event.session_id, event.client) or self.store.new(
                event.session_id, repository, event.client
            )
            if event.event_id is not None:
                fingerprint = hashlib.sha256(event.model_dump_json().encode()).hexdigest()
                for cached in session.replayed_outcomes:
                    if cached["event_id"] == event.event_id:
                        if cached["fingerprint"] != fingerprint:
                            raise HookError("event_id was reused with different input")
                        return HookOutcome.model_validate(cached["outcome"])
            session.repository = str(repository)
            session.event_count += 1
            session.recent_events.append(_event_record(event, self.config.output_limit))
            session.recent_events = session.recent_events[-self.config.event_history_limit :]

            if event.kind is HookEventKind.SESSION_STARTED:
                session.touch(self.store.ttl_seconds)
                self.store.save(session)
                return HookOutcome()
            if event.kind is HookEventKind.WORK_SUBMITTED:
                try:
                    if event.work_id is not None and event.work_id == session.work_id:
                        if session.work_prompt != event.prompt.strip():
                            raise HookError("work_id was reused with a different prompt")
                        if session.state is not None and (
                            session.state.active_extension_ids != list(self.active_extension_ids)
                            or session.state.extension_snapshot_revisions
                            != self.extension_snapshot_revisions
                        ):
                            raise HookError("extension snapshots changed; submit new work")
                        output = HookOutcome(
                            action=HookAction.INJECT_CONTEXT,
                            reason=session.routed_context,
                        ) if session.routed_context else HookOutcome()
                    else:
                        output = await self._route_prompt(session, event)
                        session.work_id = event.work_id
                        session.work_prompt = event.prompt.strip()
                        session.routed_context = output.reason
                        session.continuation_requested = False
                except ResponsibilityRoutingError as error:
                    output = HookOutcome(
                        action=HookAction.BLOCK,
                        reason=f"Foreman could not route this work: {error}",
                    )
            else:
                if session.state is None:
                    if session.prompt_routed and not self.candidates.global_ids():
                        return HookOutcome()
                    raise HookError(
                        f"{event.source_event_name} arrived before work_submitted"
                    )
                if (
                    session.state.active_extension_ids != list(self.active_extension_ids)
                    or
                    session.state.extension_snapshot_revisions
                    != self.extension_snapshot_revisions
                ):
                    raise HookError(
                        "extension snapshots changed during this attached session; "
                        "submit the work prompt again"
                    )
                if event.kind is HookEventKind.WORKER_STOPPING and session.work_id is not None:
                    event = event.model_copy(update={
                        "continuation_active": (
                            event.continuation_active or session.continuation_requested
                        ),
                    })
                output = await self._assess_event(session, event)
                if (
                    event.kind is HookEventKind.WORKER_STOPPING
                    and session.work_id is not None
                    and output.action is HookAction.BLOCK
                ):
                    session.continuation_requested = True

            if event.event_id is not None:
                session.replayed_outcomes.append({
                    "event_id": event.event_id,
                    "fingerprint": fingerprint,
                    "outcome": output.model_dump(mode="json"),
                })
                session.replayed_outcomes = session.replayed_outcomes[
                    -self.config.event_history_limit :
                ]
            self._bound_state(session)
            session.touch(self.store.ttl_seconds)
            self.store.save(session)
            return output

    async def _route_prompt(
        self, session: AttachedSession, event: HookEvent
    ) -> HookOutcome:
        assert event.prompt is not None
        decision = await resolve_hierarchical_routing(
            event.prompt.strip(),
            self.candidates,
            self.routing_groups,
            self.router,
            require_match=bool(self.candidates.global_ids()),
        )
        active_ids = decision.active_responsibility_ids
        session.prompt_routed = True
        if not active_ids:
            if not self.candidates.global_ids():
                session.state = None
                return HookOutcome()
            raise ResponsibilityRoutingError("routing activated no responsibilities")
        guidance = "\n\n".join(
            text for responsibility_id in active_ids
            if (text := self.candidates.context_for(responsibility_id))
        )
        if len(guidance) > self.config.field_limit:
            raise HookError("selected responsibility context exceeds the field limit")

        state = session.state or FactoryState(
            run_id=(
                f"attached-{AttachedSessionStore._key(session.session_id, session.client)[:16]}"
            ),
            job=event.prompt.strip(),
            repository=session.repository,
            max_iterations=self.config.max_iterations,
            candidate_responsibility_ids=[
                responsibility.id for responsibility in self.candidates.responsibilities
            ],
        )
        state.job = event.prompt.strip()
        state.repository = session.repository
        state.status = FactoryStatus.RUNNING

def grouped_responsibility_ids(
    groups: tuple[RouteGroup, ...],
    candidates: ResponsibilityRegistry,
) -> set[str]:
    """Validate a hierarchy and return responsibility IDs owned by its groups."""

    return _validate_route_groups(groups, candidates)


def prune_disabled_route_groups(
    groups: tuple[RouteGroup, ...], disabled_ids: set[str]
) -> tuple[RouteGroup, ...]:
    """Remove explicitly disabled responsibilities and groups with no remaining candidates."""
    result = []
    for group in groups:
        responsibilities = tuple(key for key in group.responsibility_ids if key not in disabled_ids)
        children = prune_disabled_route_groups(group.children, disabled_ids)
        if responsibilities or children:
            result.append(replace(group, responsibility_ids=responsibilities, children=children))
    return tuple(result)


async def resolve_hierarchical_routing(
    work: str,
    candidates: ResponsibilityRegistry,
    groups: tuple[RouteGroup, ...],
    router: ResponsibilityRouter,
    *,
    require_match: bool = True,
) -> RoutingDecision:
    """Route root responsibilities and recursively expand every matching route group."""

    if not groups:
        decision = await router.route(work, candidates)
        active = resolved_responsibility_ids(decision, candidates)
        return decision.model_copy(update={"active_responsibility_ids": active})

    assigned = _validate_route_groups(groups, candidates)
    root_ids = tuple(
        responsibility.id
        for responsibility in candidates.responsibilities
        if responsibility.id not in assigned
    )
    active_ids: set[str] = set()
    responsibility_scores: dict[str, float] = {}
    bindings: dict[str, dict[str, JsonValue]] = {}
    trace: list[RouteTraceEntry] = []

    async def route_responsibilities(responsibility_ids: tuple[str, ...]) -> None:
        if not responsibility_ids:
            return
        registry = candidates.routed(responsibility_ids)
        decision = await router.route(work, registry)
        active_ids.update(resolved_responsibility_ids(decision, registry))
        overlap = set(responsibility_scores) & set(decision.scores)
        if overlap:
            raise ResponsibilityRoutingError(
                "responsibilities were routed more than once: " + ", ".join(sorted(overlap))
            )
        responsibility_scores.update(decision.scores)

    async def route_group_level(
        level: tuple[RouteGroup, ...],
        selection: RouteSelection,
        parent_path: tuple[str, ...],
    ) -> None:
        if not level:
            return
        route_groups = getattr(router, "route_groups", None)
        if not callable(route_groups):
            raise ResponsibilityRoutingError(
                "configured router does not support hierarchical route groups"
            )
        routes = {group.id: group.route for group in level}
        decision = await route_groups(work, routes)
        known = set(routes)
        unknown = (set(decision.active_responsibility_ids) | set(decision.scores)) - known
        if unknown:
            raise ResponsibilityRoutingError(
                "routing decision references unknown groups: " + ", ".join(sorted(unknown))
            )
        selected = set(decision.active_responsibility_ids)
        selected.update(group.id for group in level if group.route.always)
        if selection is RouteSelection.BEST_MATCH:
            conditional = [
                group
                for group in level
                if not group.route.always and group.id in selected
            ]
            if conditional:
                winner = max(conditional, key=lambda group: decision.scores.get(group.id, -1.0))
                selected.difference_update(group.id for group in conditional)
                selected.add(winner.id)

        for group in level:
            matched = group.id in selected
            path = (*parent_path, group.id)
            trace.append(
                RouteTraceEntry(
                    group_id=group.id,
                    path=list(path),
                    selected=matched,
                    score=decision.scores.get(group.id),
                )
            )
            if not matched:
                continue
            if group.bindings:
                bindings[group.id] = dict(group.bindings)
            await route_responsibilities(group.responsibility_ids)
            await route_group_level(group.children, group.child_selection, path)

    await route_responsibilities(root_ids)
    await route_group_level(groups, RouteSelection.ALL_MATCHES, ())
    ordered_active = [
        responsibility.id
        for responsibility in candidates.responsibilities
        if responsibility.id in active_ids
    ]
    if not ordered_active and require_match:
        raise ResponsibilityRoutingError("routing activated no responsibilities")
    return RoutingDecision(
        active_responsibility_ids=ordered_active,
        scores=responsibility_scores,
        bindings=bindings,
        trace=trace,
    )


def _routing_key(candidate_id: str, *, prefix: str = "responsibility") -> str:
    return f"{prefix}__{candidate_id}"


def _parse_scores(
    response: Any,
    candidate_ids: list[str],
    *,
    prefix: str = "responsibility",
) -> dict[str, float]:
    keys = [_routing_key(candidate_id, prefix=prefix) for candidate_id in candidate_ids]
    raw_values = parse_jev_values(response, keys)
    values = {
        candidate_id: raw_values[key]
        for candidate_id, key in zip(candidate_ids, keys, strict=True) if key in raw_values
    }

    return _normalize_scores(values, candidate_ids)


def _normalize_scores(values: Mapping[str, Any], candidate_ids: list[str]) -> dict[str, float]:
    missing = set(candidate_ids) - set(values)
    if missing:
        raise ResponsibilityRoutingError(
            f"Decision model routing response omitted: {', '.join(sorted(missing))}"
        )

    scores: dict[str, float] = {}
    for candidate_id in candidate_ids:
        raw = values[candidate_id]
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise ResponsibilityRoutingError(
                f"Decision model routing answer for {candidate_id!r} is not numeric"
            )
        score = float(raw)
        if not isfinite(score):
            raise ResponsibilityRoutingError(
                f"Decision model routing answer for {candidate_id!r} is not finite"
            )
        scores[candidate_id] = min(1.0, max(0.0, score))
    return scores


class DecisionResponsibilityRouter:
    """Route responsibilities and groups through a decision-model adapter."""

    def __init__(
        self, adapter: DecisionModelAdapter, *, timeout_seconds: float = 10.0,
        budget: DecisionRequestBudget | None = None,
        usage_recorder: DecisionUsageRecorder | None = None,
    ) -> None:
        self.adapter = adapter
        self.timeout_seconds = timeout_seconds
        self.budget = budget or adapter.budget
        self.usage_recorder = usage_recorder or DecisionUsageRecorder()

    @property
    def model(self) -> str:
        return self.adapter.model

    @model.setter
    def model(self, value: str) -> None:
        self.adapter.model = value

    async def route(
        self,
        work: str,
        candidates: ResponsibilityRegistry,
    ) -> RoutingDecision:
        routed_ids = [
            responsibility.id
            for responsibility in candidates.responsibilities
            if not candidates.route_for(responsibility.id).always
        ]
        if not routed_ids:
            return RoutingDecision(
                active_responsibility_ids=list(candidates.global_ids()),
            )

        scores = await self._score(
            work,
            {
                responsibility_id: candidates.route_for(responsibility_id)
                for responsibility_id in routed_ids
            },
            prefix="responsibility",
        )

        active = set(candidates.global_ids())
        for responsibility_id, score in scores.items():
            if score >= candidates.route_for(responsibility_id).threshold:
                active.add(responsibility_id)
        active_ids = [
            responsibility.id
            for responsibility in candidates.responsibilities
            if responsibility.id in active
        ]
        return RoutingDecision(active_responsibility_ids=active_ids, scores=scores)

